import { test } from 'node:test'
import assert from 'node:assert/strict'
import { mkdtempSync, readdirSync, writeFileSync, existsSync } from 'node:fs'
import { tmpdir } from 'node:os'
import path from 'node:path'
import { JsonStore } from '../src/store.js'
import { Inventory } from '../src/inventory.js'

const book = (id, stock = 2) => ({ id, title: `T${id}`, author: 'A', priceCents: 1000, stock, tags: [] })

test('JsonStore round-trips, creates dirs, and writes atomically', () => {
  const dir = mkdtempSync(path.join(tmpdir(), 'h01-'))
  const file = path.join(dir, 'nested', 'deeper', 'inv.json')
  const store = new JsonStore(file)
  assert.equal(store.load(), null)
  store.save([book('a')])
  assert.deepEqual(store.load(), [book('a')])
  const leftovers = readdirSync(path.dirname(file)).filter((f) => f !== 'inv.json')
  assert.deepEqual(leftovers, [], 'no temp files left behind')
})

test('Inventory persists add/remove through the store and reloads', () => {
  const dir = mkdtempSync(path.join(tmpdir(), 'h01-'))
  const store = new JsonStore(path.join(dir, 'inv.json'))
  const inv = Inventory.fromStore(store, [book('a', 2), book('b', 5)])
  inv.add(book('a'), 3)
  inv.remove('b', 2)
  const reloaded = Inventory.fromStore(new JsonStore(path.join(dir, 'inv.json')), [])
  assert.equal(reloaded.find('a').stock, 5)
  assert.equal(reloaded.find('b').stock, 3)
})

test('fromStore falls back when the store is empty, and failed ops do not write', () => {
  const dir = mkdtempSync(path.join(tmpdir(), 'h01-'))
  const file = path.join(dir, 'inv.json')
  let saves = 0
  const store = new JsonStore(file)
  const spy = { load: () => store.load(), save: (d) => { saves++; store.save(d) } }
  const inv = Inventory.fromStore(spy, [book('x', 1)])
  assert.equal(inv.find('x').stock, 1)
  const before = saves
  assert.throws(() => inv.remove('missing', 1))
  assert.equal(saves, before, 'failed remove must not persist')
})

test('createApp uses INVENTORY_FILE when set', async () => {
  const dir = mkdtempSync(path.join(tmpdir(), 'h01-'))
  const file = path.join(dir, 'inv.json')
  writeFileSync(file, JSON.stringify([book('only', 4)]))
  process.env.INVENTORY_FILE = file
  try {
    const { createApp } = await import('../src/server.js?h01=' + Date.now())
    const res = await createApp()({ method: 'GET', url: '/books' })
    assert.deepEqual(res.body.map((b) => b.id), ['only'])
  } finally {
    delete process.env.INVENTORY_FILE
  }
  assert.ok(existsSync(file))
})

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createApp } from '../src/server.js'
import { Inventory } from '../src/inventory.js'

test('orders: create, stock decrement, all-or-nothing, lookup, listing', async () => {
  const app = createApp(Inventory.fromFile())
  const call = (method, url, body) => app({ method, url, body })

  const ok = await call('POST', '/orders', { items: [{ id: 'b6', quantity: 1 }] })
  assert.equal(ok.status, 201)
  assert.equal(ok.body.id, 'ord_1')
  assert.equal(ok.body.totalCents, 3239)
  assert.ok(!Number.isNaN(Date.parse(ok.body.createdAt)))
  assert.equal((await call('GET', '/books/b6')).body.stock, 8)

  // b8 has 1 in stock: the whole order must fail and nothing may change
  const conflict = await call('POST', '/orders', { items: [{ id: 'b6', quantity: 1 }, { id: 'b8', quantity: 2 }] })
  assert.equal(conflict.status, 409)
  assert.equal(conflict.body.item, 'b8')
  assert.equal(typeof conflict.body.error, 'string')
  assert.equal((await call('GET', '/books/b6')).body.stock, 8)
  assert.equal((await call('GET', '/books/b8')).body.stock, 1)

  for (const body of [{}, { items: [] }, { items: [{ id: 'nope', quantity: 1 }] }, { items: [{ id: 'b1', quantity: 0 }] }]) {
    assert.equal((await call('POST', '/orders', body)).status, 400, JSON.stringify(body))
  }

  const second = await call('POST', '/orders', { items: [{ id: 'b1', quantity: 2 }], discountCode: 'WELCOME10' })
  assert.equal(second.status, 201)
  assert.equal(second.body.id, 'ord_2')

  assert.equal((await call('GET', '/orders/ord_1')).body.totalCents, 3239)
  assert.equal((await call('GET', '/orders/ord_9')).status, 404)
  assert.deepEqual((await call('GET', '/orders')).body.map((o) => o.id), ['ord_2', 'ord_1'])
})

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { Router } from '../src/router.js'
import { createApp } from '../src/server.js'
import { Inventory } from '../src/inventory.js'

const hdr = (r, k) => Object.fromEntries(Object.entries(r.headers ?? {}).map(([a, b]) => [a.toLowerCase(), String(b)]))[k]

test('router middleware order, short-circuit and 404', async () => {
  const r = new Router()
  const seen = []
  r.use(async (ctx, next) => { seen.push('a'); ctx.state.a = 1; return next() })
  r.use(async (ctx, next) => { seen.push('b'); if (ctx.path === '/blocked') return { status: 403, body: { error: 'no' } }; return next() })
  r.get('/hello/:name', (ctx) => ({ status: 200, body: { hi: ctx.params.name, a: ctx.state.a } }))
  const ok = await r.dispatch({ method: 'GET', path: '/hello/x', query: new URLSearchParams(), headers: {}, body: {} })
  assert.equal(ok.status, 200)
  assert.deepEqual(ok.body, { hi: 'x', a: 1 })
  assert.deepEqual(seen, ['a', 'b'])
  const blocked = await r.dispatch({ method: 'GET', path: '/blocked', query: new URLSearchParams(), headers: {}, body: {} })
  assert.equal(blocked.status, 403)
  const missing = await r.dispatch({ method: 'GET', path: '/nope', query: new URLSearchParams(), headers: {}, body: {} })
  assert.equal(missing.status, 404)
})

test('errors: status-carrying errors pass through, others become a generic 500', async () => {
  const r = new Router()
  r.get('/teapot', () => { const e = new Error('short and stout'); e.status = 418; throw e })
  r.get('/boom', () => { throw new Error('secret internals') })
  const t = await r.dispatch({ method: 'GET', path: '/teapot', query: new URLSearchParams(), headers: {}, body: {} })
  assert.deepEqual([t.status, t.body.error], [418, 'short and stout'])
  const b = await r.dispatch({ method: 'GET', path: '/boom', query: new URLSearchParams(), headers: {}, body: {} })
  assert.equal(b.status, 500)
  assert.equal(b.body.error, 'Internal error')
})

test('app: request ids on every response and API-key auth for mutating routes', async () => {
  delete process.env.API_KEYS
  const app = createApp(Inventory.fromFile())
  const open = await app({ method: 'POST', url: '/cart/quote', body: { items: [{ id: 'b6', quantity: 1 }] } })
  assert.equal(open.status, 200)
  assert.ok(hdr(open, 'x-request-id'))
  process.env.API_KEYS = 'k1, k2'
  try {
    const denied = await app({ method: 'POST', url: '/cart/quote', headers: {}, body: { items: [{ id: 'b6', quantity: 1 }] } })
    assert.equal(denied.status, 401)
    const allowed = await app({ method: 'POST', url: '/cart/quote', headers: { 'x-api-key': 'k2' }, body: { items: [{ id: 'b6', quantity: 1 }] } })
    assert.equal(allowed.status, 200)
    const get = await app({ method: 'GET', url: '/books' })
    assert.equal(get.status, 200)
    assert.ok(hdr(get, 'x-request-id'))
    assert.notEqual(hdr(get, 'x-request-id'), hdr(allowed, 'x-request-id'))
  } finally {
    delete process.env.API_KEYS
  }
  const crash = await app({ method: 'POST', url: '/cart/quote', body: {} })
  assert.equal(crash.status, 500)
  assert.equal(crash.body.error, 'Internal error')
})

