import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createApp } from '../src/server.js'
import { Inventory } from '../src/inventory.js'

const hdr = (r, k) => Object.fromEntries(Object.entries(r.headers ?? {}).map(([a, b]) => [a.toLowerCase(), String(b)]))[k]

test('ETag + If-None-Match on book reads', async () => {
  const inv = Inventory.fromFile()
  const app = createApp(inv)
  const first = await app({ method: 'GET', url: '/books', headers: {} })
  const etag = hdr(first, 'etag')
  assert.match(etag, /^"[0-9a-f]{40}"$/)
  const again = await app({ method: 'GET', url: '/books', headers: { 'if-none-match': etag } })
  assert.equal(again.status, 304)
  assert.ok(again.body === undefined || again.body === null || again.body === '')
  inv.add({ id: 'b1' }, 1)
  const changed = await app({ method: 'GET', url: '/books', headers: { 'if-none-match': etag } })
  assert.equal(changed.status, 200)
  assert.notEqual(hdr(changed, 'etag'), etag)
  const one = await app({ method: 'GET', url: '/books/b2', headers: {} })
  assert.ok(hdr(one, 'etag'))
})

test('token-bucket rate limiting per client with an injectable clock', async () => {
  let t = 1_000_000
  const app = createApp(Inventory.fromFile(), { rateLimit: { capacity: 2, refillPerSec: 1 }, now: () => t })
  const hit = (client) => app({ method: 'GET', url: '/health', headers: client ? { 'x-client-id': client } : {} })
  assert.equal((await hit('a')).status, 200)
  assert.equal((await hit('a')).status, 200)
  const limited = await hit('a')
  assert.equal(limited.status, 429)
  assert.ok(Number(hdr(limited, 'retry-after')) >= 1)
  assert.equal((await hit('b')).status, 200, 'clients are independent')
  assert.equal((await hit()).status, 200, 'anonymous bucket')
  t += 1000
  assert.equal((await hit('a')).status, 200, 'refilled after a second')
})

test('defaults do not limit normal use', async () => {
